def compare_csv(path:Path,expected,columns):
    with path.open(newline="") as f:actual=list(csv.DictReader(f));y.require(list(actual[0])==list(columns) and len(actual)==len(expected),f"CSV shape drift: {path}");
    for a,e in zip(actual,expected):
        for c in columns:
            av=a[c];ev=e.get(c);
            if ev is None:y.require(av=="",f"CSV null drift: {path}/{c}")
            elif isinstance(ev,bool):y.require(av==str(ev),f"CSV bool drift: {path}/{c}")
            elif isinstance(ev,(int,float)):y.require(math.isclose(float(av),float(ev),rel_tol=0,abs_tol=0),f"CSV numeric drift: {path}/{c}")
            else:y.require(av==str(ev),f"CSV string drift: {path}/{c}")
